-- Migration V025: ALTER IDENTITY to BY DEFAULT for sync ID coordination.
-- Allows explicit ID inserts from the sync service without OVERRIDING clause.
-- Auto-generated IDs still work for normal app inserts.

ALTER TABLE articulos.familias
    ALTER COLUMN "familia_id" SET GENERATED BY DEFAULT;

ALTER TABLE articulos.grupos
    ALTER COLUMN "grupo_id" SET GENERATED BY DEFAULT;

ALTER TABLE articulos."unidadesMedida"
    ALTER COLUMN "unidadMedida_id" SET GENERATED BY DEFAULT;

ALTER TABLE articulos."alicuotasIva"
    ALTER COLUMN "alicuotaIva_id" SET GENERATED BY DEFAULT;

ALTER TABLE articulos."impuestosInternos"
    ALTER COLUMN "impuestoInterno_id" SET GENERATED BY DEFAULT;
